<script lang="ts">
  import type {PageData,ActionData} from './$types';
  let {data,form}:{data:PageData;form:ActionData}=$props();
  import {enhance} from '$app/forms';
  import {useI18n,type Key} from '$lib/i18n';
  let greetingBusy=$state(false);
  let contextBusy=$state(false);
  const kb=(n:number)=>n>=1048576?`${(n/1048576).toFixed(1)} MB`:`${Math.max(1,Math.round(n/1024))} KB`;
  const {t,locale}=useI18n();
  const fmt=(d:string)=>new Date(d).toLocaleDateString(locale,{day:'numeric',month:'short',year:'numeric'});
  const time=(ms:number)=>`${Math.floor(ms/60000)}:${String(Math.floor(ms/1000)%60).padStart(2,'0')}`;
</script>
<div class="main"><header class="row" style="justify-content:space-between"><a href="/dashboard">{t('proj.back')}</a><a href={`/p/${data.project.slug}`} class="pill">{t('proj.link')}</a></header><div class="eyebrow" style="margin-top:45px">{t('proj.eyebrow',{status:data.project.status})}</div><h1 style="font-size:clamp(2.4rem,6vw,4rem)">{data.project.title}</h1><p class="muted" style="font-size:1.2rem">{data.project.question}</p><div class="row" style="flex-wrap:wrap;margin:24px 0"><a class="btn" href={`/p/${data.project.slug}`}>{t('proj.startRec')}</a><a class="btn secondary" href={`/dashboard/projects/${data.project.id}/nodes`}>{t('proj.map')}</a><a class="btn secondary" href={`/dashboard/projects/${data.project.id}/reels`}>{t('proj.reels')}</a><button class="btn secondary" onclick={()=>navigator.clipboard.writeText(`${location.origin}/p/${data.project.slug}`)}>{t('proj.copyLink')}</button></div>
<form method="POST" action="?/setMode" use:enhance={()=>async({update})=>update({reset:false})} class="row" style="flex-wrap:wrap;margin-bottom:18px"><label class="tiny">{t('dash.mode')} <select class="field" name="capture_mode" value={data.project.capture_mode} onchange={(e)=>e.currentTarget.form?.requestSubmit()}><option value="video">{t('mode.video')}</option><option value="audio">{t('mode.audio')}</option><option value="either">{t('mode.either')}</option></select></label></form>
<section class="panel stack" style="margin-bottom:18px"><div><div class="eyebrow">{t('greet.eyebrow')}</div><p class="tiny muted" style="margin:4px 0 0">{t('greet.hint')}</p></div>
  {#if data.greeting.uploaded}<audio controls preload="none" src={`/api/public/greeting/${data.project.id}?v=${data.greeting.version}`} style="width:100%"></audio>
  {:else if data.greeting.externalUrl}<p class="tiny muted">{t('greet.external')} <code style="overflow-wrap:anywhere">{data.greeting.externalUrl}</code></p>
  {:else}<p class="tiny muted">{t('greet.none')}</p>{/if}
  <form method="POST" action="?/uploadGreeting" enctype="multipart/form-data" use:enhance={()=>{greetingBusy=true;return async({update})=>{await update({reset:true});greetingBusy=false}}} class="row" style="flex-wrap:wrap">
    <input class="field" style="flex:1;min-width:220px;margin:0" type="file" name="greeting" accept="audio/*,.mp3,.wav,.m4a,.ogg,.webm" required />
    <button class="btn" disabled={greetingBusy}>{greetingBusy?t('greet.uploading'):data.greeting.uploaded?t('greet.replace'):t('greet.upload')}</button>
  </form>
  {#if data.greeting.uploaded}<form method="POST" action="?/removeGreeting" use:enhance><button class="btn secondary">{t('greet.remove')}</button></form>{/if}
  {#if form?.greetingError}<p class="error" role="alert">{t(`greet.err.${form.greetingError}` as Key)}</p>{:else if form?.greetingSaved}<p class="tiny muted">{t('greet.saved')}</p>{/if}
</section>
<section class="panel stack" style="margin-bottom:18px"><div><div class="eyebrow">{t('ctx.eyebrow')}</div><p class="tiny muted" style="margin:4px 0 0">{t('ctx.hint')}</p></div>
  {#if data.contextDocs.length}<div>{#each data.contextDocs as d}<div class="row" style="justify-content:space-between;flex-wrap:wrap;border-bottom:2px solid #000;padding:10px 0"><span><strong>{d.title}</strong> <span class="pill">{d.kind}</span> <span class="pill">{d.status}</span><br><small class="muted">{#if d.analysis?.pages}{t('ctx.pages',{n:d.analysis.pages})} · {/if}{t('ctx.stats',{chars:(d.analysis?.chars??0).toLocaleString(locale),n:d.analysis?.chunks??0})}{#if d.size_bytes} · {kb(d.size_bytes)}{/if} · {fmt(d.created_at)}{#if d.analysis?.extract} · {t('ctx.extracted',{n:d.analysis.statements??0})}{#if d.status!=='ready'} ({d.analysis.cursor??0}/{d.analysis.chunks??0}){/if}{/if}</small></span>
    <form method="POST" action="?/removeContext" use:enhance><input type="hidden" name="sourceId" value={d.id}><button class="btn secondary">{t('ctx.remove')}</button></form></div>{/each}</div>
  {:else}<p class="tiny muted">{t('ctx.none')}</p>{/if}
  <form method="POST" action="?/addContextFile" enctype="multipart/form-data" use:enhance={()=>{contextBusy=true;return async({update})=>{await update({reset:true});contextBusy=false}}} class="row" style="flex-wrap:wrap">
    <input class="field" style="flex:1;min-width:220px;margin:0" type="file" name="file" accept="application/pdf,text/plain,.pdf,.txt,.md" required />
    <input class="field" style="flex:1;min-width:160px;margin:0" name="title" maxlength="160" placeholder={t('ctx.titlePh')} />
    <label class="tiny row" style="gap:6px;flex-basis:100%"><input type="checkbox" name="extract" checked />{t('ctx.extract')}</label>
    <button class="btn" disabled={contextBusy}>{contextBusy?t('ctx.uploading'):t('ctx.upload')}</button>
  </form>
  <form method="POST" action="?/addContextText" use:enhance={()=>{contextBusy=true;return async({update})=>{await update({reset:true});contextBusy=false}}} class="stack">
    <input class="field" name="title" maxlength="160" placeholder={t('ctx.titlePh')} />
    <textarea class="field" name="text" rows="5" placeholder={t('ctx.textPh')} required></textarea>
    <label class="tiny row" style="gap:6px"><input type="checkbox" name="extract" checked />{t('ctx.extract')}</label>
    <div><button class="btn secondary" disabled={contextBusy}>{contextBusy?t('ctx.uploading'):t('ctx.addText')}</button></div>
  </form>
  {#if form?.contextError}<p class="error" role="alert">{t(`ctx.err.${form.contextError}` as Key)}</p>{:else if form?.contextSaved}<p class="tiny muted">{t('ctx.saved',{title:form.contextSaved.title,n:form.contextSaved.chunks})}</p>{/if}
</section>
<section class="grid"><div class="panel"><div class="eyebrow">{t('proj.videos')}</div><div class="big-number">{data.sources.length}</div></div><div class="panel"><div class="eyebrow">{t('proj.themes')}</div><div class="big-number">{data.themes.length}</div></div><div class="panel"><div class="eyebrow">{t('proj.highlightSuggestions')}</div><div class="big-number">{data.highlights.length}</div></div></section>
{#if data.report && data.report.report && typeof data.report.report==='object'}<section class="panel" style="margin-top:18px"><div class="eyebrow">{t('proj.lastReport')}</div><h2>{t('proj.noticed')}</h2><p class="muted">{(data.report.report as {latestSourceSummary?:string}).latestSourceSummary??t('proj.noSummary')}</p><small class="muted">{t('proj.reportNote')}</small></section>{/if}
<section class="grid" style="margin-top:18px"><div class="panel"><h2>{t('proj.detected')}</h2>{#if data.themes.length}{#each data.themes as th}<div class="row" style="justify-content:space-between;border-bottom:2px solid #000;padding:10px 0"><span>{th.name}{#if th.description}<br><small class="muted">{th.description}</small>{/if}</span><span class="muted">{t('proj.sources',{n:th.source_count})}{#if th.text_count} <span class="pill">{t('proj.inText',{n:th.text_count})}</span>{/if}</span></div>{#each th.insights as i}<details style="padding:8px 0 8px 14px;border-bottom:1px solid #000"><summary><strong>{i.title}</strong>{#if i.description}<br><small class="muted">{i.description}</small>{/if}</summary><ul class="tiny" style="padding-left:1.2em;margin:8px 0 0">{#each i.evidence as e}<li style="margin-bottom:6px">{e.text}<br><span class="muted">{#if e.from_text}<span class="pill">{t('proj.fromText')}</span> {/if}{e.source}{#if e.page} · {t('ctx.page',{n:e.page})}{/if}{#if e.start_ms!==null} · {time(e.start_ms)}{/if}</span></li>{/each}</ul></details>{/each}{/each}{:else}<p class="muted">{t('proj.themesLater')}</p>{/if}</div><div class="panel"><h2>{t('proj.recordings')}</h2>{#if !data.sources.length}<p class="muted">{t('proj.noContrib')}</p>{/if}{#each data.sources as s}<div style="padding:14px 0;border-bottom:2px solid #000"><strong>{s.title}</strong> <span class="pill">{s.status}</span> <small class="muted">{fmt(s.created_at)}</small>{#if s.stale}<form method="POST" action="?/reprocess" use:enhance style="display:inline"><input type="hidden" name="sourceId" value={s.id}><button class="btn secondary" type="submit" title={t('proj.reprocessHint')}>{t('proj.reprocess')}</button></form>{/if}{#if s.status==='ready'}{#if s.kind==='audio'||s.mime_type?.startsWith('audio/')}<audio controls preload="metadata" src={`/api/dashboard/media/${s.id}`} style="display:block;margin-top:12px;width:100%;max-width:420px"></audio>{:else}<video controls preload="metadata" playsinline src={`/api/dashboard/media/${s.id}`} style="display:block;margin-top:12px;border-radius:10px;max-height:220px"></video>{/if}{/if}{#if s.analysis && typeof s.analysis==='object'}<p class="muted tiny">{(s.analysis as {summary?:string}).summary??''}</p>{/if}<p class="tiny muted">{s.id}</p></div>{/each}</div></section>
<section class="panel" style="margin-top:18px"><h2>{t('proj.highlights')}</h2><p class="muted tiny">{t('proj.highlightsNote')}</p>{#if data.highlights.length===0}<p class="muted">{t('proj.highlightsEmptyA')} `npm run render -- &lt;highlight-id&gt;`.</p>{/if}{#each data.highlights as h}<div style="padding:16px 0;border-bottom:2px solid #000"><strong>{h.title}</strong> · <span class="muted">{Array.isArray(h.clips)&&h.clips.length>0?t('proj.clips',{n:h.clips.length})+' · ':time(h.start_ms)+'–'+time(h.end_ms)+' · '}{h.status}</span><p class="muted">{h.reason}</p>{#if h.status==='suggested'}<form method="POST" action="?/approveHighlight"><input type="hidden" name="highlightId" value={h.id}/><button class="btn secondary" style="margin:10px 0">{t('proj.approve')}</button></form>{/if}{#if h.status==='rendered'}<video controls playsinline preload="metadata" src={`/api/dashboard/highlight/${h.id}`} style="max-height:300px;border-radius:12px"></video>{/if}</div>{/each}</section>
</div>
